inline void CSpriteFrame::Clip(int& sx, int& sy, int& sw, int& sh,
                               int& dx, int& dy, int dw, int dh,
                               unsigned char hflip,
                               unsigned char vflip) const
{
    int deltaX;

    if (hflip)
        sx = Width - sx - sw;
    if (vflip)
        sy = Height - sy - sh;

    if (dx < 0) {
        if (!hflip)
            sx -= dx;
        sw += dx;
        dx = 0;
    }
    if (dy < 0) {
        if (!vflip)
            sy -= dy;
        sh += dy;
        dy = 0;
    }
    if (sw + dx > dw) {
        if (hflip)
            sx += sw + dx - dw;
        sw = dw - dx;
    }
    if (sh + dy > dh) {
        if (vflip)
            sy += sh + dy - dh;
        sh = dh - dy;
    }

    if (sx < CroppedX) {
        deltaX = CroppedX - sx;
        if (!hflip)
            dx += deltaX;
        sw -= deltaX;
        sx = CroppedX;
    }
    if (sy < CroppedY) {
        deltaX = CroppedY - sy;
        if (!vflip)
            dy += deltaX;
        sh -= deltaX;
        sy = CroppedY;
    }
    deltaX = CroppedWidth + CroppedX;
    if (sw + sx > deltaX) {
        if (hflip)
            dx += sw + sx - deltaX;
        sw = deltaX - sx;
    }
    deltaX = CroppedHeight + CroppedY;
    if (sh + sy > deltaX) {
        if (vflip)
            dy += sh + sy - deltaX;
        sh = deltaX - sy;
    }

    sx -= CroppedX;
    sy -= CroppedY;
}

